import 'quiz_question.dart';

/// A quiz generated by the backend from a course (and optionally one of its
/// learning resources).
class Quiz {
  final String id;
  final String courseId;

  /// Null for a quiz about the whole course.
  final String? resourceId;
  final String title;
  final String description;
  final int passingPercentage;
  final List<QuizQuestion> questions;

  const Quiz({
    required this.id,
    required this.courseId,
    required this.resourceId,
    required this.title,
    required this.description,
    required this.passingPercentage,
    required this.questions,
  });

  bool get isCourseQuiz => resourceId == null;

  factory Quiz.fromJson(Map<String, dynamic> json) {
    return Quiz(
      id: json['id'] as String,
      courseId: json['courseId'] as String,
      resourceId: json['resourceId'] as String?,
      title: json['title'] as String,
      description: json['description'] as String? ?? '',
      passingPercentage: (json['passingPercentage'] as num?)?.toInt() ?? 60,
      questions: (json['questions'] as List? ?? const [])
          .whereType<Map>()
          .map((q) => QuizQuestion.fromJson(Map<String, dynamic>.from(q)))
          .toList(),
    );
  }
}